#include<bits/stdc++.h>

using namespace std;
using ll=long long;

int main(){
  int t;
  cin >> t;
  while(t--){
    int n;
    cin >> n;
    string str;
    cin >> str;
    vector<ll> x(n),y(n-1);
    for(auto &nx : x){cin >> nx;}
    for(auto &nx : y){cin >> nx;}
    ll s=0,r=0;
    if(str[0]=='R'){s=-x[0];}
    else{r=-x[0];}
    for(int i=1;i<n;i++){
      ll ns=max(s,r+y[i-1]);
      ll nr=max(s,r);
      if(str[i]=='R'){ns-=x[i];}
      else{nr-=x[i];}
      s=ns;
      r=nr;
    }
    cout << max(s,r) << "\n";
  }
  return 0;
}
